1	import { Box, Popover } from '@mui/material';
2	import { useCallback, useEffect, useRef, useState } from 'react';
3	import {
4	    SEARCH_OPEN_REQUESTED_EVENT,
5	    searchOpenService,
6	} from '../../../services/search/search_open_service';
7	import type { SearchRegexpAgent } from '../../../services/search/search_types';
8	import { NO_DRAG_REGION } from '../drag_region';
9	import { SearchPanel } from './search_panel';
10	import { SearchLauncher } from './search_launcher';
11	import { SEARCH_PLACEHOLDERS, type SearchPresentation } from './search_field_styles';
12	
13	const RESULTS_WIDTH = 460;
14	
15	interface SearchControlProps {
16	    isMobile?: boolean;
17	    presentation?: SearchPresentation;
18	    /** Builds a RegExp from the current query; defaults to the not-yet-available agent. */
19	    regexpAgent?: SearchRegexpAgent;
20	}
21	
22	/** Lightweight launcher; narrow headers open the editable search in an anchored popover. */
23	export function SearchControl(props: SearchControlProps) {
24	    const { isMobile = false, presentation = 'full', regexpAgent } = props;
25	    const [query, setQuery] = useState('');
26	    const [isOpen, setIsOpen] = useState(false);
27	    const [searchAnchorElement, setSearchAnchorElement] = useState<HTMLElement | null>(null);
28	    const controlElement = useRef<HTMLDivElement | null>(null);
29	    const launcherPresentation = isMobile ? 'icon' : presentation;
30	    const usesPopover = isMobile || presentation === 'icon' || presentation === 'shortcut';
31	
32	    const openSearch = useCallback(() => {
33	        const anchorElement = controlElement.current;
34	        if (!anchorElement) throw new Error('Cannot open search without its anchor');
35	        setSearchAnchorElement(anchorElement);
36	        setIsOpen(true);
37	    }, []);
38	
39	    useEffect(() => {
40	        searchOpenService.addEventListener(SEARCH_OPEN_REQUESTED_EVENT, openSearch);
41	
42	        return () => searchOpenService.removeEventListener(SEARCH_OPEN_REQUESTED_EVENT, openSearch);
43	    }, [openSearch]);
44	
45	    const closeSearch = () => {
46	        setIsOpen(false);
47	    };
48	
49	    const updateQuery = (nextQuery: string) => {
50	        setQuery(nextQuery);
51	    };
52	
53	    return (
54	        <Box data-search-presentation={launcherPresentation} ref={controlElement} style={NO_DRAG_REGION} sx={{ position: 'relative', width: '100%' }}>
55	            <SearchLauncher
56	                isOpen={isOpen && !usesPopover}
57	                onOpen={openSearch}
58	                presentation={launcherPresentation}
59	                query={query}
60	            />
61	            {isOpen && !usesPopover ? (
62	                <SearchPanel
63	                    initialQuery={query}
64	                    onClose={closeSearch}
65	                    onQueryChange={updateQuery}
66	                    placeholder={SEARCH_PLACEHOLDERS[presentation]}
67	                    regexpAgent={regexpAgent}
68	                />
69	            ) : null}
70	            <Popover
71	                anchorEl={searchAnchorElement}
72	                anchorOrigin={{ horizontal: 'right', vertical: 'bottom' }}
73	                disableAutoFocus
74	                onClose={closeSearch}
75	                open={isOpen && usesPopover}
76	                slotProps={{paper: { sx: { mt: 0.5, overflow: 'visible', p: 1, width: `min(${RESULTS_WIDTH}px, calc(100vw - 32px))` } }}}
77	                transformOrigin={{ horizontal: 'right', vertical: 'top' }}
78	            >
79	                {isOpen && usesPopover ? (
80	                    <SearchPanel initialQuery={query} onClose={closeSearch} onQueryChange={updateQuery} regexpAgent={regexpAgent} />
81	                ) : null}
82	            </Popover>
83	        </Box>
84	    );
85	}
