1	import { Box, IconButton, InputAdornment, TextField, Tooltip } from '@mui/material';
2	import Magnify from 'mdi-material-ui/Magnify';
3	import { GLOBAL_SEARCH_SHORTCUT_BINDING } from '../../../services/search/search_open_service';
4	import { formatShortcut } from '../../../services/shortcuts/keyboard_platform';
5	import { NO_DRAG_REGION } from '../drag_region';
6	import { SEARCH_INPUT_STYLES, SEARCH_PLACEHOLDERS, SEARCH_SHORTCUT_STYLES, type SearchPresentation } from './search_field_styles';
7	
8	interface SearchLauncherProps {
9	    isOpen: boolean;
10	    onOpen: () => void;
11	    presentation: SearchPresentation;
12	    query: string;
13	}
14	
15	/** Keeps complete shortcut measurements available even when the launcher becomes an icon. */
16	export function SearchLauncher({ isOpen, onOpen, presentation, query }: SearchLauncherProps) {
17	    const shortcutLabel = formatShortcut(GLOBAL_SEARCH_SHORTCUT_BINDING);
18	
19	    return (
20	        <>
21	            <Box
22	                aria-hidden
23	                data-search-metrics
24	                sx={{
25	                    alignItems: 'center', border: 1, display: 'flex', fontSize: 13, gap: 1, pointerEvents: 'none',
26	                    left: 0, position: 'fixed', px: 1.5, top: 0, visibility: 'hidden', whiteSpace: 'nowrap', width: 'max-content',
27	                }}
28	            >
29	                <Magnify data-search-icon fontSize="small" />
30	                <Box component="span" data-search-label><span data-search-word>Search</span> cards…</Box>
31	                <Box data-search-shortcut sx={{ ...SEARCH_SHORTCUT_STYLES, '&::after': { content: JSON.stringify(shortcutLabel) } }} />
32	            </Box>
33	            {!isOpen && presentation === 'icon' ? (
34	                <Tooltip title={`Search (${shortcutLabel})`}>
35	                    <IconButton aria-label="Search" onClick={onOpen} size="small" style={NO_DRAG_REGION} sx={{ height: 32, width: 32 }}>
36	                        <Magnify fontSize="small" />
37	                    </IconButton>
38	                </Tooltip>
39	            ) : null}
40	            {!isOpen && presentation !== 'icon' ? (
41	                <TextField
42	                    fullWidth
43	                    onClick={onOpen}
44	                    onFocus={onOpen}
45	                    placeholder={SEARCH_PLACEHOLDERS[presentation]}
46	                    size="small"
47	                    slotProps={{
48	                        htmlInput: { 'aria-label': 'Search project', readOnly: true },
49	                        input: {
50	                            endAdornment: (
51	                                <InputAdornment position="end">
52	                                    <Box component="span" sx={SEARCH_SHORTCUT_STYLES}>{shortcutLabel}</Box>
53	                                </InputAdornment>
54	                            ),
55	                            startAdornment: <InputAdornment position="start"><Magnify fontSize="small" /></InputAdornment>,
56	                            sx: SEARCH_INPUT_STYLES,
57	                        },
58	                    }}
59	                    style={NO_DRAG_REGION}
60	                    value={query}
61	                    variant="outlined"
62	                />
63	            ) : null}
64	        </>
65	    );
66	}
